import sys


def main():
    d = sys.stdin.read().split()
    n = int(d[0])
    a = list(map(int, d[1:1 + n]))
    lo, hi = min(a), max(a)
    if lo == hi:
        print(1)
        return
    last_lo = last_hi = -1
    best = n
    for i, v in enumerate(a):
        if v == lo:
            last_lo = i
            if last_hi >= 0:
                best = min(best, i - last_hi + 1)
        elif v == hi:
            last_hi = i
            if last_lo >= 0:
                best = min(best, i - last_lo + 1)
    print(best)


